// Des: Tests for sy-clou-stor and the three S3 vendor presets
// Flo: fake S3 transport (signature checked, paging) > put/get/del/list > presets > key pairs
// I/O: fake HTTP > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const stor = @import("sy-clou-stor.zig"); const base = @import("nt-vend-base.zig"); const s3v4 = @import("sy-clou-s3v4.zig"); const cfgz = @import("cf-conf-load.zig"); const b2zz = @import("sy-clou-b2zz.zig"); const r2zz = @import("sy-clou-r2zz.zig"); const tigr = @import("sy-clou-tigr.zig");
const allo = std.testing.allocator;
const Fake = struct { map: std.StringHashMapUnmanaged([]u8) = .empty, calls: usize = 0, badsig: usize = 0, lastq: [128]u8 = undefined, lastn: usize = 0,
pub fn deinit(self: *Fake) void { var iter = self.map.iterator(); while (iter.next()) |ent| { allo.free(ent.key_ptr.*); allo.free(ent.value_ptr.*); } self.map.deinit(allo); }
pub fn send(self: *Fake) base.Send { return .{ .ctx = self, .call = callz }; }
fn callz(ctx: *anyopaque, gpaz: std.mem.Allocator, _: std.Io, http: base.Http) anyerror!base.Back { const self: *Fake = @ptrCast(@alignCast(ctx)); self.calls += 1; if (!std.mem.startsWith(u8, http.auth, "AWS4-HMAC-SHA256 Credential=") or http.extra.len != 2) self.badsig += 1; const rest = http.urlz["https://".len..]; const slash = std.mem.findScalar(u8, rest, '/').?; const pq = rest[slash..]; const qix = std.mem.findScalar(u8, pq, '?'); const path = if (qix) |q| pq[0..q] else pq; const query = if (qix) |q| pq[q + 1 ..] else ""; if (std.mem.eql(u8, http.meth, "PUT")) { const key = try allo.dupe(u8, path); const val = try allo.dupe(u8, http.body); if (self.map.fetchRemove(key)) |old| { allo.free(old.key); allo.free(old.value); } try self.map.put(allo, key, val); return .{ .code = 200, .body = try gpaz.dupe(u8, "") }; } if (std.mem.eql(u8, http.meth, "DELETE")) { if (self.map.fetchRemove(path)) |old| { allo.free(old.key); allo.free(old.value); } return .{ .code = 204, .body = try gpaz.dupe(u8, "") }; }
if (query.len == 0) { const val = self.map.get(path) orelse return .{ .code = 404, .body = try gpaz.dupe(u8, "") }; return .{ .code = 200, .body = try gpaz.dupe(u8, val) }; } const n = @min(query.len, self.lastq.len); @memcpy(self.lastq[0..n], query[0..n]); self.lastn = n; var keys: std.ArrayList([]const u8) = .empty; defer keys.deinit(allo); var iter = self.map.iterator(); while (iter.next()) |ent| try keys.append(allo, ent.key_ptr.*); std.mem.sort([]const u8, keys.items, {}, struct { fn lt(_: void, a: []const u8, b: []const u8) bool { return std.mem.lessThan(u8, a, b); } }.lt); const skip: usize = if (std.mem.indexOf(u8, query, "continuation-token=") != null) 2 else 0; var xml: std.ArrayList(u8) = .empty; defer xml.deinit(allo); var shown: usize = 0; for (keys.items, 0..) |key, ix| { if (ix < skip or shown >= 2) continue; const bare = key["/bkt/".len..]; try xml.print(allo, "<Contents><Key>{s}</Key><Size>{d}</Size></Contents>", .{ bare, self.map.get(key).?.len }); shown += 1; } const more = keys.items.len > skip + 2; try xml.print(allo, "<IsTruncated>{s}</IsTruncated>{s}", .{ if (more) "true" else "false", if (more) "<NextContinuationToken>tok/1</NextContinuationToken>" else "" }); return .{ .code = 200, .body = try gpaz.dupe(u8, xml.items) }; } };
fn mk(fak: *Fake) stor.S3 { return .{ .cred = .{ .akey = "AK", .skey = "SK", .regn = "auto", .host = "h.example.com" }, .bukt = "bkt", .send = fak.send(), .gpaz = allo }; }
test "put, get, delete round trip, every call is signed" { var fak: Fake = .{}; defer fak.deinit(); var s3 = mk(&fak); const sto = s3.store(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try sto.put(sto.ctx, aren.allocator(), std.testing.io, "runs/a b.pack", "DATA"); const got = try sto.get(sto.ctx, aren.allocator(), std.testing.io, "runs/a b.pack"); try std.testing.expectEqualStrings("DATA", got); try sto.del(sto.ctx, aren.allocator(), std.testing.io, "runs/a b.pack"); try std.testing.expectError(error.CloudHttp, sto.get(sto.ctx, aren.allocator(), std.testing.io, "runs/a b.pack")); try std.testing.expectEqual(@as(usize, 0), fak.badsig); }
test "list pages through continuation tokens and filters by prefix query" { var fak: Fake = .{}; defer fak.deinit(); var s3 = mk(&fak); const sto = s3.store(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const nams = [_][]const u8{ "runs/1.pack", "runs/2.pack", "runs/3.pack", "runs/4.pack", "runs/5.pack" }; for (nams) |nam| try sto.put(sto.ctx, aren.allocator(), std.testing.io, nam, "xyz"); const objs = try sto.list(sto.ctx, aren.allocator(), std.testing.io, "runs/"); try std.testing.expect(objs.len >= 4); try std.testing.expectEqual(@as(u64, 3), objs[0].size); try std.testing.expect(std.mem.indexOf(u8, fak.lastq[0..fak.lastn], "list-type=2&prefix=runs%2F") != null); try std.testing.expect(std.mem.indexOf(u8, fak.lastq[0..fak.lastn], "continuation-token=tok%2F1") != null); }
test "vendor presets: B2 host from region, R2 needs a host, Tigris default host" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const pair: stor.Pair = .{ .akey = "a", .skey = "s" }; const conf: cfgz.Conf = .{}; const bb = try b2zz.credMake(aren.allocator(), conf.clou_endp.b2zz, pair); try std.testing.expectEqualStrings("s3.us-west-004.backblazeb2.com", bb.host); try std.testing.expectError(error.BadConfig, r2zz.credMake(aren.allocator(), conf.clou_endp.r2zz, pair)); const rr = try r2zz.credMake(aren.allocator(), .{ .hostz = "acct.r2.cloudflarestorage.com" }, pair); try std.testing.expectEqualStrings("auto", rr.regn); const tt = try tigr.credMake(aren.allocator(), conf.clou_endp.tigr, pair); try std.testing.expectEqualStrings("t3.storage.dev", tt.host); }
test "key pair needs two non-empty lines" { const pair = try stor.keyPair(" AKEY \r\n SECRET \nignored"); try std.testing.expectEqualStrings("AKEY", pair.akey); try std.testing.expectEqualStrings("SECRET", pair.skey); try std.testing.expectError(error.NoKey, stor.keyPair("only one")); try std.testing.expectError(error.NoKey, stor.keyPair("a\n \n")); try std.testing.expectError(error.NoKey, stor.keyPair("")); }
